// IDA V2: no scheduled worker - a background completion still waiting (a retry, a stock-lock wait, a parked second phase, a closed
// browser) moves on when this list opens (at most every 2 minutes per browser). Switch off or id not set: no call, no storage.
(() => {
  const ASYNC_IDA_ENABLED = false;
  const WORKER = "2112749010379997186"; // IDA_V2_WORKER
  const KEY = "ida_v2_worker_kick_at";
  if (ASYNC_IDA_ENABLED !== true || !/^[1-9][0-9]{0,19}$/.test(WORKER)) return;
  let last = 0;
  try {
    last = Number(localStorage.getItem(KEY) || 0);
  } catch (e) {}
  if (Date.now() - last < 120000) return;
  try {
    localStorage.setItem(KEY, String(Date.now()));
  } catch (e) {}
  const tick = (round) => {
    try {
      const p = this.runWorkflow(
        WORKER,
        { job_id: "" },
        (w) => {
          const processed = Number((w && w.data && w.data.processed) || 0);
          if (processed > 0) {
            this.refresh();
            if (round < 40) tick(round + 1);
          }
        },
        (e) => console.error("IDA V2: worker tick failed", e),
      );
      if (p && typeof p.catch === "function") p.catch(() => {});
    } catch (e) {
      console.error("IDA V2: worker could not be started", e);
    }
  };
  tick(1);
})();

(async () => {
  try {
    const row = arguments[0]?.row;
    if (!row || !row.id) {
      this.$message.error("No Item Disassembly selected.");
      return;
    }

    const label = row.stock_movement_no || row.id;
    // List rows carry dictionary fields as { dict_key }, the form as a plain string.
    const statusOf = (value) => value?.dict_key ?? value;
    const status = statusOf(row.item_disassembly_status);

    // Once a disassembly is completed the source item has left stock and the
    // recovered components have been received; deleting the document would
    // strand both. A Processing one is being completed in the background.
    const UNDELETABLE = ["Completed", "Fully Posted", "Processing"];
    if (UNDELETABLE.includes(status)) {
      this.$message.error(
        `Item Disassembly ${label} is ${status} and cannot be deleted.`
      );
      return;
    }

    // stock_movement_no is free text under the Manual Input serial rule, so it
    // cannot go into an HTML confirm unescaped.
    const escapeHtml = (value) =>
      String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    await this.$confirm(
      `Delete Item Disassembly <strong>${escapeHtml(
        label
      )}</strong>?<br>This cannot be undone.`,
      "Item Disassembly Deletion",
      {
        confirmButtonText: "Delete",
        cancelButtonText: "Cancel",
        type: "warning",
        dangerouslyUseHTMLString: true,
      }
    ).catch(() => {
      throw new Error("cancelled");
    });

    // The grid can be stale (a background job may hold it now): the stored status decides.
    const storedRes = await db
      .collection("sm_item_disassembly")
      .where({ id: row.id, is_deleted: 0 })
      .field("item_disassembly_status")
      .get();
    const stored = (storedRes && storedRes.data && storedRes.data[0]) || null;
    const storedStatus = stored ? statusOf(stored.item_disassembly_status) : "";
    if (!stored || UNDELETABLE.includes(storedStatus)) {
      this.$message.error(
        stored
          ? `Item Disassembly ${label} is ${storedStatus} and cannot be deleted.`
          : `Item Disassembly ${label} is no longer available.`
      );
      this.refresh();
      return;
    }

    await db
      .collection("sm_item_disassembly")
      .doc(row.id)
      .update({ is_deleted: 1 });

    // Both subforms are real child tables; leaving them behind orphans them.
    const CHILD_TABLES = [
      "sm_item_disassembly_tlm8ve69_sub",
      "sm_item_disassembly_mw10kf66_sub",
    ];

    await Promise.all(
      CHILD_TABLES.map(async (table) => {
        const children = await db
          .collection(table)
          .where({ sm_item_disassembly_id: row.id, is_deleted: 0 })
          .get()
          .catch(() => ({ data: [] }));

        await Promise.all(
          (children.data || []).map((child) =>
            db
              .collection(table)
              .doc(child.id)
              .update({ is_deleted: 1 })
              .catch((error) =>
                console.error(`Error deleting ${table} row:`, error)
              )
          )
        );
      })
    );

    this.refresh();
    this.$message.success(`Item Disassembly ${label} deleted.`);
  } catch (error) {
    if (error?.message === "cancelled") return;
    console.error(error);
    this.$message.error(
      error?.message || "Failed to delete the Item Disassembly"
    );
  }
})();

// Chunked id reads with an explicit limit (the API clamps a read at IDA_READ_MAX rows, as GDonMounted.js); a short answer is read
// again for the ids it left out; a failed read rejects
const IDA_READ_CHUNK = 500;
const IDA_READ_MAX = 5000;
const idaChunks = (list, size) => {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
};
const idaUniq = (list) => [...new Set((list || []).filter((v) => v !== undefined && v !== null && v !== "").map(String))];
// rows of `collection` whose id is in `ids` (is_deleted 0), `fields` projected
const idaReadIds = async (collection, ids, fields) => {
  const rows = [];
  await Promise.all(
    idaChunks(idaUniq(ids), Math.min(IDA_READ_CHUNK, IDA_READ_MAX)).map(async (chunk) => {
      let left = chunk;
      while (left.length) {
        let query = db.collection(collection).filter([
          {
            type: "branch",
            operator: "all",
            children: [
              { prop: "id", operator: "in", value: left },
              { prop: "is_deleted", operator: "equal", value: 0 },
            ],
          },
        ]);
        if (fields) query = query.field(fields);
        const res = await query.limit(left.length).get();
        const got = (res && res.data) || [];
        rows.push(...got);
        const seen = new Set(got.map((row) => String(row.id)));
        const missing = left.filter((id) => !seen.has(id));
        if (!got.length || missing.length === left.length) return;
        left = missing;
      }
    }),
  );
  return { data: rows };
};

const callPostItemDisassemblyWorkflow = async (selectedRecords, aiData) => {
  switch (aiData.acc_integration_type) {
    case "SQL Accounting V2":
    case "AutoCount Accounting V2":
      await Promise.all(
        selectedRecords.map(async (item) => {
          await db
            .collection("sm_item_disassembly")
            .doc(item.id)
            .update({ posted_status: "Pending Post" });
        }),
      );

      this.$message.success("Item Disassembly sent for posting.");
      this.refresh();
      this.hideLoading();
      await this.runWorkflow(
        "2013511169625042946",
        {
          agent_id: aiData.agent_id,
          task_type: "post_item_disassembly",
          payload: selectedRecords.map((item) => item.id),
          priority: "0",
        },
        async (res) => {
          console.log("成功结果：", res);
        },
        (err) => {
          console.log("失败结果：", err);
        },
      );
      break;

    default:
      console.log(
        "No post handler for accounting integration type:",
        aiData.acc_integration_type,
      );
      break;
  }
};

(async () => {
  try {
    const allListID = "custom_7rq6zmn4";
    const organizationID = this.getVarGlobal("firstLvDeptId");
    this.showLoading("Posting Item Disassembly...");

    let selectedRecords;

    selectedRecords = this.getComponent(allListID)?.$refs.crud.tableSelect || [];

    console.log("selectedRecords", selectedRecords);

    // List rows carry dictionary fields as { dict_key }, not plain strings.
    const dictValue = (value) => value?.dict_key ?? value;
    const getPostedStatus = (item) => dictValue(item.posted_status);

    selectedRecords = selectedRecords.filter((item) => {
      if (dictValue(item.item_disassembly_status) !== "Completed") {
        return false;
      }

      const postedStatus = getPostedStatus(item);
      return (
        postedStatus === "Unposted" ||
        postedStatus === "Failed Post" ||
        postedStatus === "" ||
        postedStatus === null ||
        postedStatus === undefined
      );
    });

    if (selectedRecords.length === 0) {
      this.hideLoading();
      await this.$alert(
        "No selected records are available for posting. Please select records with status 'Completed' and not yet posted.",
        "No Records to Post",
        {
          confirmButtonText: "OK",
          dangerouslyUseHTMLString: true,
          type: "warning",
        },
      );
      return;
    }

    // The grid can be stale (a background job may hold a row now, or it was posted since): the stored status decides.
    const [resAI, storedRes] = await Promise.all([
      db
        .collection("accounting_integration")
        .where({ organization_id: organizationID })
        .get(),
      idaReadIds(
        "sm_item_disassembly",
        selectedRecords.map((item) => item.id),
        "item_disassembly_status,posted_status",
      ),
    ]);
    const storedKey = (value) => String(dictValue(value) ?? "").trim();
    const stored = new Map((storedRes.data || []).map((row) => [String(row.id), row]));
    const postable = (item) => {
      const row = stored.get(String(item.id));
      return !!row && storedKey(row.item_disassembly_status) === "Completed" &&
        ["Unposted", "Failed Post", ""].indexOf(storedKey(row.posted_status)) >= 0;
    };
    const changed = selectedRecords.filter((item) => !postable(item));
    selectedRecords = selectedRecords.filter(postable);
    if (changed.length > 0) {
      const why = (item) => {
        const row = stored.get(String(item.id));
        return row ? [storedKey(row.item_disassembly_status) || "no status", storedKey(row.posted_status)].filter((x) => x).join(", ") : "no longer available";
      };
      this.$message.warning(`Not posted, changed since the list loaded: ${changed.map((item) => `${item.stock_movement_no || item.id} (${why(item)})`).join("; ")}`);
    }
    if (selectedRecords.length === 0) {
      this.refresh();
      this.hideLoading();
      return;
    }

    if (resAI && resAI.data && resAI.data.length > 0) {
      const aiData = resAI.data[0];
      await callPostItemDisassemblyWorkflow(selectedRecords, aiData);
    }

    await this.getComponent(allListID)?.$refs.crud.clearSelection();
    this.refresh();
    this.hideLoading();
  } catch (error) {
    this.hideLoading();
    console.error(error);
    this.$message.error(error?.message || "Failed to post the Item Disassembly");
  }
})();
